def titulo():
    return t("The solar system, the universe, and energy sources", "El sistema solar, el universo y las fuentes de energía")


def anc(en, es):
    return en if C.L == "en" else es


def R(x):
    return f'<span class="raiz">{x}</span>'


def svg_bigbang():
    tr = {"Corrimiento al rojo": "Redshift", "La luz de las galaxias llega": "Light from galaxies arrives", "con longitud de onda más larga.": "with longer wavelengths.",
          "Se alejan de nosotros,": "They are moving away from us,", "y las más lejanas, más rápido": "and the farthest, fastest",
          "Radiación de fondo": "Background radiation", "Radiación débil y uniforme": "Faint, even radiation", "que llega de todas partes.": "coming from every direction.",
          "Resto del calor de un": "Leftover heat from a", "universo denso y caliente": "dense, hot early universe",
          "Elementos ligeros": "Light elements", "La proporción de hidrógeno": "The share of hydrogen", "y helio que se observa…": "and helium we observe…",
          "…coincide con la que": "…matches what", "el modelo predice": "the model predicts",
          "El universo se expande": "The universe is expanding", "y tuvo un origen común": "and had a common origin",
          "Tres observaciones independientes que apuntan a lo mismo": "Three independent observations that point to the same thing"}
    return C.svg_orig("7-3_0", tr, "The three lines of evidence for the Big Bang theory, shown as three boxes that lead to one conclusion. The first is redshift: light from distant galaxies arrives shifted toward longer wavelengths, which shows they are moving away from us, and the farther away they are, the faster they move away. The second is the cosmic microwave background: faint, even radiation coming from every direction in the sky, understood as the leftover heat of an early universe that was much denser and hotter. The third is the amount of light elements: the share of hydrogen and helium seen in the universe matches what the model predicts. The three lines are independent of each other and point to the same conclusion: the universe is expanding and had a common origin.")


