def tabla_fuentes():
    return C.tabla(t("Illustrative comparison of energy sources: renewable or not, greenhouse-gas emissions over the whole life cycle, whether they produce all the time, relative cost, and other impacts", "Comparación ilustrativa de fuentes de energía: si son renovables, emisiones de gases de efecto invernadero en todo su ciclo de vida, si producen de forma continua, coste relativo y otros impactos"),
        [t("Source", "Fuente"), t("Renewable?", "¿Renovable?"), t("Emissions (g CO₂ per kWh, rounded)", "Emisiones (g de CO₂ por kWh, redondeadas)"), t("Produces all the time?", "¿Produce de forma continua?"), t("Relative cost", "Coste relativo"), t("Other impacts", "Otros impactos")],
        [[t(*n), t("Yes", "Sí") if r else "No", f"{e:,}", t("Yes", "Sí") if d else t("No (intermittent)", "No (intermitente)"), t(*c), t(*i)] for n, r, e, d, c, i in FUENTES])


