# ---------------------------------------------------------------- práctica
def banco_sistema():
    d = [(t("Which group is Jupiter in?", "¿En qué grupo está Júpiter?"), [t("Giant (outer) planets", "Planetas gigantes (exteriores)"), t("Rocky (inner) planets", "Planetas rocosos (interiores)"), t("Dwarf planets", "Planetas enanos")], 0, t("Huge, mostly gas, many moons and rings.", "Enorme, de gases, muchas lunas y anillos.")),
         (t("Which planet is rocky?", "¿Qué planeta es rocoso?"), [t("Mars", "Marte"), t("Saturn", "Saturno"), t("Neptune", "Neptuno")], 0, t("Mercury, Venus, Earth, Mars.", "Mercurio, Venus, la Tierra, Marte.")),
         (t("Where is the asteroid belt?", "¿Dónde está el cinturón de asteroides?"), [t("Between Mars and Jupiter", "Entre Marte y Júpiter"), t("Between Earth and the Moon", "Entre la Tierra y la Luna"), t("Beyond Neptune", "Más allá de Neptuno")], 0, t("It separates the rocky and giant planets.", "Separa los rocosos de los gigantes.")),
         (t("What is Pluto classed as today?", "¿Cómo se clasifica hoy Plutón?"), [t("A dwarf planet in the Kuiper belt", "Planeta enano del cinturón de Kuiper"), t("A giant planet", "Planeta gigante"), t("A moon of Neptune", "Luna de Neptuno")], 0, t("Reclassified as a dwarf planet.", "Reclasificado como planeta enano.")),
         (t("If gravity suddenly vanished, Earth would…", "Si la gravedad desapareciera de golpe, la Tierra…"), [t("fly off in a straight line", "saldría despedida en línea recta"), t("fall into the Sun", "caería hacia el Sol"), t("stop moving", "dejaría de moverse")], 0, t("First law: with no force, straight line at constant speed.", "Primera ley: sin fuerza, línea recta a velocidad constante.")),
         (t("Why doesn’t a planet need an engine to keep orbiting?", "¿Por qué un planeta no necesita motor para seguir en órbita?"), [t("There is no friction in space, so its speed does not wear off", "En el espacio no hay fricción, así que su velocidad no se pierde"), t("The Sun pushes it forward", "El Sol lo empuja hacia delante"), t("Planets have no mass", "Los planetas no tienen masa")], 0, t("First law of motion.", "Primera ley del movimiento.")),
         (t("A satellite in orbit is…", "Un satélite en órbita está…"), [t("falling toward Earth all the time, but moving forward so fast it never reaches it", "cayendo continuamente hacia la Tierra, pero avanza tan rápido que nunca la alcanza"), t("floating because there is no gravity up there", "flotando porque allí no hay gravedad"), t("held up by the air", "sostenido por el aire")], 0, t("Gravity still acts in orbit.", "La gravedad sigue actuando en órbita.")),
         (t("Giant planets, compared with rocky ones, are…", "Los planetas gigantes, comparados con los rocosos, son…"), [t("bigger but less dense", "más grandes pero menos densos"), t("smaller and denser", "más pequeños y densos"), t("closer to the Sun", "más cercanos al Sol")], 0, t("Gases and ices: low density.", "Gases y hielos: poca densidad."))]
    return [{"enun": f"<p>{q}</p>", "ops": o, "ok": k, "pista": t("Rocky: small, dense, inner. Giants: huge, gas, outer. Orbit = gravity + forward speed.", "Rocosos: pequeños, densos, interiores. Gigantes: enormes, de gases, exteriores. Órbita = gravedad + velocidad."), "exp": e} for q, o, k, e in d]


MAG = [(("the Earth–Sun distance", "la distancia Tierra–Sol"), 1.5, 8), (("the Earth–Moon distance", "la distancia Tierra–Luna"), 3.8, 5), (("the Neptune–Sun distance", "la distancia Neptuno–Sol"), 4.5, 9), (("the diameter of the Sun", "el diámetro del Sol"), 1.4, 6), (("the diameter of Earth", "el diámetro de la Tierra"), 1.3, 4)]
SUP = str.maketrans("-0123456789", "⁻⁰¹²³⁴⁵⁶⁷⁸⁹")


def banco_magnitudes():
    rnd = random.Random(73)
    out = []
    pares = [(i, j) for i in range(5) for j in range(5) if MAG[i][2] > MAG[j][2]]
    rnd.shuffle(pares)
    for i, j in pares[:10]:
        a, b = MAG[i], MAG[j]
        dif = a[2] - b[2]
        razon = a[1] / b[1] * 10 ** dif
        nom_a, nom_b = t(*a[0]), t(*b[0])
        va, vb = f"{a[1]} × 10{str(a[2]).translate(SUP)} km", f"{b[1]} × 10{str(b[2]).translate(SUP)} km"
        if rnd.random() < 0.5:
            q = t(f"How many orders of magnitude apart are {nom_a} ({va}) and {nom_b} ({vb})?", f"¿Cuántos órdenes de magnitud separan {nom_a} ({va}) y {nom_b} ({vb})?")
            ops = [str(dif), str(dif + 1), str(max(dif - 1, 0)) if dif > 1 else str(dif + 2), str(a[2] + b[2])]
            if len(set(ops)) < 4:
                ops = [str(dif), str(dif + 1), str(dif + 2), str(a[2] + b[2] + 1)]
            exp = t(f"Compare exponents: {a[2]} − {b[2]} = {dif}.", f"Compare exponentes: {a[2]} − {b[2]} = {dif}.")
        else:
            r = round(razon, -len(str(int(razon))) + 2) if razon >= 100 else round(razon)
            def f(x):
                return f"{int(x):,}"
            q = t(f"About how many times larger is {nom_a} ({va}) than {nom_b} ({vb})?", f"¿Cuántas veces mayor es, aproximadamente, {nom_a} ({va}) que {nom_b} ({vb})?")
            ops = [f(r), f(r * 10), f(max(r // 10, 1)) if r >= 20 else f(r * 100), f(a[1] / b[1] * 100) if f(a[1] / b[1] * 100) not in (f(r), f(r * 10)) else f(r * 1000)]
            if len(set(ops)) < 4:
                ops = [f(r), f(r * 10), f(r * 100), f(r * 1000)]
            exp = t(f"{a[1]} ÷ {b[1]} ≈ {a[1] / b[1]:.2g}, and 10{str(a[2]).translate(SUP)} ÷ 10{str(b[2]).translate(SUP)} = 10{str(dif).translate(SUP)}: about {f(r)} times.", f"{a[1]} ÷ {b[1]} ≈ {a[1] / b[1]:.2g}, y 10{str(a[2]).translate(SUP)} ÷ 10{str(b[2]).translate(SUP)} = 10{str(dif).translate(SUP)}: unas {f(r)} veces.")
        out.append({"enun": f"<p>{q}</p>", "ops": ops, "ok": 0, "pista": t("Subtract the exponents first; then divide the front numbers if you need more precision.", "Reste primero los exponentes; después divida los números de delante si hace falta más precisión."), "exp": exp})
    out.append({"enun": "<p>" + t("Light travels at 3 × 10⁸ m/s and takes about 8 minutes to reach us from the Sun. What we see of the Sun is…", "La luz viaja a 3 × 10⁸ m/s y tarda unos 8 minutos en llegar desde el Sol. Lo que vemos del Sol es…") + "</p>",
                "ops": [t("how it was about 8 minutes ago", "cómo era hace unos 8 minutos"), t("how it is right now", "cómo es en este mismo instante"), t("how it was 8 years ago", "cómo era hace 8 años")], "ok": 0,
                "pista": t("Light takes time to travel.", "La luz tarda en viajar."), "exp": t("Even at the speed of light, 1.5 × 10⁸ km takes about 8 minutes.", "Incluso a la velocidad de la luz, 1.5 × 10⁸ km llevan unos 8 minutos.")})
    return out


def banco_bigbang():
    O = [t("Redshift", "Corrimiento al rojo"), t("Cosmic microwave background", "Radiación de fondo de microondas"), t("Amount of light elements", "Abundancia de elementos ligeros")]
    d = [(t("Light from distant galaxies arrives with longer wavelengths than expected.", "La luz de las galaxias lejanas llega con longitudes de onda más largas de lo esperado."), 0),
         (t("A faint, even glow of microwaves comes from every direction in the sky.", "Un brillo débil y uniforme de microondas llega de todas las direcciones del cielo."), 1),
         (t("About three quarters of ordinary matter is hydrogen and about one quarter is helium, as the model predicts.", "Unas tres cuartas partes de la materia ordinaria son hidrógeno y una cuarta parte helio, como predice el modelo."), 2),
         (t("The farther away a galaxy is, the faster it is moving away.", "Cuanto más lejos está una galaxia, más rápido se aleja."), 0),
         (t("Leftover heat from a time when the universe was much denser and hotter.", "Calor residual de una época en que el universo era mucho más denso y caliente."), 1),
         (t("The lightest elements on the periodic table are the most common in the universe.", "Los elementos más ligeros de la tabla periódica son los más abundantes del universo."), 2)]
    out = [{"enun": t("Which line of evidence is this?", "¿Qué línea de evidencia es?") + f"<br><strong>{x}</strong>", "ops": O, "ok": k, "enOrden": True,
            "pista": t("Stretched light → redshift; glow from everywhere → background; hydrogen and helium → light elements.", "Luz estirada → corrimiento al rojo; brillo de todas partes → radiación de fondo; hidrógeno y helio → elementos ligeros."), "exp": f"<strong>{O[k]}.</strong>"} for x, k in d]
    otras = [(t("Where did the carbon and iron in your body form?", "¿Dónde se formaron el carbono y el hierro de su cuerpo?"), [t("Inside stars", "En el interior de las estrellas"), t("On Earth’s surface", "En la superficie de la Tierra"), t("In the Moon", "En la Luna")], 0, t("Heavier elements were made later, in stars.", "Los elementos pesados se fabricaron después, en las estrellas.")),
             (t("Why do three independent lines of evidence make the Big Bang theory strong?", "¿Por qué tres líneas de evidencia independientes hacen fuerte la teoría del Big Bang?"), [t("They measure different things and still agree", "Miden cosas distintas y aun así coinciden"), t("They are the same measurement repeated", "Son la misma medición repetida"), t("Three is a lucky number", "Tres es un número de suerte")], 0, t("The same rule as Wegener and evolution.", "El mismo criterio que con Wegener y la evolución.")),
             (t("A light source moving <strong>toward</strong> us would shift toward…", "Una fuente de luz que se <strong>acerca</strong> se desplazaría hacia…"), [t("blue (shorter waves)", "el azul (ondas más cortas)"), t("red (longer waves)", "el rojo (ondas más largas)"), t("no change", "ningún cambio")], 0, t("Squeezed waves: shorter wavelength.", "Ondas comprimidas: menor longitud de onda."))]
    for q, o, k, e in otras:
        out.append({"enun": f"<p>{q}</p>", "ops": o, "ok": k, "pista": t("Think about waves (6.3), atoms (5.1), and independent evidence (7.1).", "Piense en las ondas (6.3), los átomos (5.1) y la evidencia independiente (7.1)."), "exp": e})
    return out


def banco_fuentes():
    rnd = random.Random(74)
    nom = [t(*f[0]) for f in FUENTES]
    out = []
    preguntas = []
    ren = [i for i, f in enumerate(FUENTES) if f[1]]; noren = [i for i, f in enumerate(FUENTES) if not f[1]]
    cont = [i for i, f in enumerate(FUENTES) if f[3]]
    preguntas.append((t("Which source has the <strong>lowest</strong> emissions?", "¿Qué fuente tiene las emisiones <strong>más bajas</strong>?"), min(range(7), key=lambda i: FUENTES[i][2])))
    preguntas.append((t("Which source has the <strong>highest</strong> emissions?", "¿Qué fuente tiene las emisiones <strong>más altas</strong>?"), max(range(7), key=lambda i: FUENTES[i][2])))
    preguntas.append((t("Which <strong>nonrenewable</strong> source has the lowest emissions?", "¿Qué fuente <strong>no renovable</strong> tiene las emisiones más bajas?"), min(noren, key=lambda i: FUENTES[i][2])))
    preguntas.append((t("Which <strong>renewable</strong> source has the highest emissions?", "¿Qué fuente <strong>renovable</strong> tiene las emisiones más altas?"), max(ren, key=lambda i: FUENTES[i][2])))
    preguntas.append((t("Which <strong>renewable</strong> source produces <strong>all the time</strong> and has emissions under 50?", "¿Qué fuente <strong>renovable</strong> produce <strong>de forma continua</strong> y emite menos de 50?"), [i for i in ren if FUENTES[i][3] and FUENTES[i][2] < 50][0]))
    preguntas.append((t("Which source produces all the time and has the <strong>highest</strong> emissions after coal?", "¿Qué fuente produce de forma continua y tiene las emisiones <strong>más altas</strong> después del carbón?"), sorted(cont, key=lambda i: -FUENTES[i][2])[1]))
    for q, k in preguntas:
        otros = [i for i in range(7) if i != k]
        rnd.shuffle(otros)
        ops = [nom[k]] + [nom[i] for i in otros[:3]]
        out.append({"enun": "<p>" + t("Use the data table in section 3 of the lesson (shown again here).", "Use la tabla de datos de la sección 3 de la lección (se repite aquí).") + "</p>" + tabla_fuentes() + f"<p><strong>{q}</strong></p>", "ops": ops, "ok": 0,
                    "pista": t("Find the column the question names and read only that one (plus any filter it adds).", "Busque la columna que nombra la pregunta y lea solo esa (más el filtro que añada)."), "exp": t(f"{nom[k]}: {FUENTES[k][2]:,} g CO₂ per kWh.", f"{nom[k]}: {FUENTES[k][2]:,} g de CO₂ por kWh.")})
    return out


def clasif_afirmaciones():
    G = [t("Supported by the table", "Sostenida por la tabla"), t("Goes beyond the data", "Excede los datos")]
    PI = [t("Is it limited to a column of the table?", "¿Se limita a una columna de la tabla?"), t("Does it claim “best”, “always”, “no drawbacks”, or something the table does not measure?", "¿Afirma «la mejor», «siempre», «sin inconvenientes» o algo que la tabla no mide?")]
    def item(tit, piezas):
        return {"titulo": tit, "intro": t("Use the data table in section 3. Sort each claim.", "Use la tabla de datos de la sección 3. Clasifique cada afirmación."), "grupos": G, "etiqueta": t("This claim is:", "La afirmación está:"),
                "piezas": [{"t": a, "v": v, "pista": PI[v]} for a, v in piezas], "extra": t("Supported claims name a criterion and stay inside the table; absolute claims and superlatives with no criterion go too far.", "Las afirmaciones sostenidas nombran un criterio y se quedan dentro de la tabla; las absolutas y los superlativos sin criterio se exceden.")}
    return [
        item(t("Set 1", "Grupo 1"), [(t("In the table, wind has the lowest emissions.", "En la tabla, la eólica tiene las emisiones más bajas."), 0), (t("Wind is the best energy source.", "La eólica es la mejor fuente de energía."), 1), (t("Coal emits more than any other source in the table.", "El carbón emite más que cualquier otra fuente de la tabla."), 0), (t("Nuclear power is completely safe.", "La energía nuclear es totalmente segura."), 1), (t("Solar and wind do not produce all the time.", "La solar y la eólica no producen de forma continua."), 0)]),
        item(t("Set 2", "Grupo 2"), [(t("Every renewable source emits less than every nonrenewable one.", "Toda fuente renovable emite menos que cualquier no renovable."), 1), (t("Biomass is renewable but emits more than nuclear.", "La biomasa es renovable, pero emite más que la nuclear."), 0), (t("Solar will be the cheapest source in 2050.", "La solar será la fuente más barata en 2050."), 1), (t("In the table, natural gas emits less than coal.", "En la tabla, el gas natural emite menos que el carbón."), 0), (t("Hydroelectric dams have no impact on rivers.", "Las presas hidroeléctricas no afectan a los ríos."), 1)]),
    ]


def practica():
    A = {"en": ["solar-system", "big-bang", "energy"], "es": ["sistema-solar", "big-bang", "energia"]}[C.L]
    mods = [
        (A[0], t("The solar system and orbits", "El sistema solar y las órbitas"), C.om("m1", t("Planet groups and what keeps them in orbit.", "Grupos de planetas y qué los mantiene en órbita.")) + "\n" + C.om("m2", t("Compare distances and sizes in powers of ten.", "Compare distancias y tamaños en potencias de diez."))),
        (A[1], t("The evidence for the Big Bang", "La evidencia del Big Bang"), C.om("m3", t("Which observation is it, and what does it show?", "¿Qué observación es y qué demuestra?"))),
        (A[2], t("Compare energy sources", "Compare fuentes de energía"), C.om("m4", t("Read the column the question asks for.", "Lea la columna que pide la pregunta.")) + "\n" + C.clasifica("m5")),
    ]
    js = (C.js_datos("SIS", banco_sistema()) + C.js_datos("MAG", banco_magnitudes()) + C.js_datos("BIG", banco_bigbang()) + C.js_datos("FUE", banco_fuentes()) + C.js_datos("AFI", clasif_afirmaciones()) +
          'creaBanco("m1", SIS);\ncreaBanco("m2", MAG);\ncreaBanco("m3", BIG);\ncreaBanco("m4", FUE);\ncreaClasifica("m5", AFI);\n')
    return C.pagina_practica(N, titulo(), t("Three activities · new exercises every time · two tries in each one · calculator included", "Tres actividades · ejercicios nuevos cada vez · dos intentos en cada uno · con calculadora"), mods, js, calculadora=True)


if __name__ == "__main__":
    C.construye(N, leccion, practica)
